//! Typed gRPC reflection descriptors synthesized from `PluginSchema.methods`
//! (REQ-6.1): per-method `FileDescriptorProto`s with real field types derived
//! from `MethodDecl.args` / `MethodDecl.returns` JSON Schemas — never
//! `google.protobuf.Struct`.
//!
//! Naming follows the spec's acceptance criterion (Task 3.2):
//!
//! ```text
//! file:    operation/method/<plugin>/<method>.proto
//! package: operation.method.<plugin>.<method>
//! service: <Method>Service   rpc <Method>(<Method>Input) returns (<Method>Output)
//! ```
//!
//! The protobuf wire encoding is written by hand (varint + length-delimited
//! fields of descriptor.proto messages) so the crate stays dependency-free.
//! The bytes are a valid `google.protobuf.FileDescriptorSet` consumable by
//! tonic-reflection / grpcurl.

use crate::schema::{MethodDecl, PluginSchema};
use serde_json::Value as JVal;

// FieldDescriptorProto.Type values (descriptor.proto)
const T_DOUBLE: u64 = 1;
const T_INT64: u64 = 3;
const T_BOOL: u64 = 8;
const T_STRING: u64 = 9;
const T_MESSAGE: u64 = 11;
// FieldDescriptorProto.Label values
const L_OPTIONAL: u64 = 1;
const L_REPEATED: u64 = 3;

/// One synthesized per-method descriptor file plus its reflection index keys.
#[derive(Debug, Clone)]
pub struct MethodDescriptor {
    pub method_name: String,
    pub file_name: String,
    pub package: String,
    /// Fully-qualified service name, e.g. `operation.method.unix_socket.bind.BindService`.
    pub service_full: String,
    /// `/package.Service/Rpc` — the callable route path.
    pub grpc_path: String,
    pub input_full: String,
    pub output_full: String,
    /// All fully-qualified symbols this file defines (for symbol lookup).
    pub symbols: Vec<String>,
    /// Encoded `FileDescriptorProto` bytes.
    pub file_descriptor_proto: Vec<u8>,
}

/// Synthesize the full `FileDescriptorSet` for one plugin, one file per
/// method, sorted by method name for byte determinism (NFR-2).
pub fn descriptor_set_for_plugin(
    plugin_id: &str,
    schema: &PluginSchema,
) -> (Vec<u8>, Vec<MethodDescriptor>) {
    let mut names: Vec<&String> = schema.methods.keys().collect();
    names.sort();
    let mut infos = Vec::new();
    let mut set = Vec::new();
    for name in names {
        let info = method_file_descriptor(plugin_id, &schema.methods[name]);
        // FileDescriptorSet.file = 1 (repeated message)
        put_bytes(&mut set, 1, &info.file_descriptor_proto);
        infos.push(info);
    }
    (set, infos)
}

/// Build one per-method `FileDescriptorProto` with typed Input/Output messages.
pub fn method_file_descriptor(plugin_id: &str, method: &MethodDecl) -> MethodDescriptor {
    let snake = snake_case(&method.name);
    let pascal = pascal_case(&method.name);
    let package = format!("operation.method.{plugin_id}.{snake}");
    let file_name = format!("operation/method/{plugin_id}/{snake}.proto");

    let input_msg = message_from_json_schema(&format!("{pascal}Input"), &method.args);
    let empty = serde_json::json!({"type": "object"});
    let output_schema = method.returns.as_ref().unwrap_or(&empty);
    let output_msg = message_from_json_schema(&format!("{pascal}Output"), output_schema);

    let input_full = format!("{package}.{pascal}Input");
    let output_full = format!("{package}.{pascal}Output");
    let service_full = format!("{package}.{pascal}Service");

    // MethodDescriptorProto
    let mut m = Vec::new();
    put_str(&mut m, 1, &pascal);
    put_str(&mut m, 2, &format!(".{input_full}"));
    put_str(&mut m, 3, &format!(".{output_full}"));

    // ServiceDescriptorProto
    let mut svc = Vec::new();
    put_str(&mut svc, 1, &format!("{pascal}Service"));
    put_bytes(&mut svc, 2, &m);

    // FileDescriptorProto
    let mut file = Vec::new();
    put_str(&mut file, 1, &file_name);
    put_str(&mut file, 2, &package);
    put_bytes(&mut file, 4, &encode_message(&input_msg));
    put_bytes(&mut file, 4, &encode_message(&output_msg));
    put_bytes(&mut file, 6, &svc);
    put_str(&mut file, 12, "proto3");

    let mut symbols = vec![service_full.clone(), input_full.clone(), output_full.clone()];
    symbols.push(format!("{service_full}.{pascal}"));
    collect_nested_symbols(&input_msg, &format!("{package}.{}", input_msg.name), &mut symbols);
    collect_nested_symbols(&output_msg, &format!("{package}.{}", output_msg.name), &mut symbols);

    MethodDescriptor {
        method_name: method.name.clone(),
        grpc_path: format!("/{service_full}/{pascal}"),
        file_name,
        package,
        service_full,
        input_full,
        output_full,
        symbols,
        file_descriptor_proto: file,
    }
}

// ---------------------------------------------------------------------------
// JSON Schema -> DescriptorProto message synthesis
// ---------------------------------------------------------------------------

struct MessageDef {
    name: String,
    fields: Vec<FieldDef>,
    nested: Vec<MessageDef>,
}

struct FieldDef {
    name: String,
    number: u64,
    repeated: bool,
    proto_type: u64,
    /// Relative type name for `T_MESSAGE` fields (a nested message).
    type_name: Option<String>,
}

/// Walk a schemars JSON Schema document into a proto message definition.
/// Objects with properties become nested messages; scalars map directly;
/// enums/unknown/any degrade to string (JSON-encoded).
fn message_from_json_schema(msg_name: &str, schema: &JVal) -> MessageDef {
    let defs = schema
        .get("$defs")
        .or_else(|| schema.get("definitions"))
        .and_then(JVal::as_object);
    build_message(msg_name, resolve(schema, defs), defs)
}

fn build_message(
    name: &str,
    node: &JVal,
    defs: Option<&serde_json::Map<String, JVal>>,
) -> MessageDef {
    let mut fields = Vec::new();
    let mut nested = Vec::new();
    if let Some(props) = node.get("properties").and_then(JVal::as_object) {
        // serde_json Map is BTreeMap-backed: iteration (and thus field
        // numbering) is name-sorted and deterministic.
        for (i, (fname, fnode)) in props.iter().enumerate() {
            let number = (i + 1) as u64;
            let (repeated, item) = match unwrap_array(fnode, defs) {
                Some(item) => (true, item),
                None => (false, resolve(fnode, defs).clone()),
            };
            let (proto_type, type_name) = proto_type_of(&item, defs, fname, &mut nested);
            fields.push(FieldDef {
                name: fname.clone(),
                number,
                repeated,
                proto_type,
                type_name,
            });
        }
    }
    MessageDef {
        name: name.to_string(),
        fields,
        nested,
    }
}

/// If `node` is an array schema, return its resolved item schema.
fn unwrap_array(node: &JVal, defs: Option<&serde_json::Map<String, JVal>>) -> Option<JVal> {
    let node = resolve(node, defs);
    if json_type(node) == Some("array") {
        let item = node.get("items").map(|i| resolve(i, defs).clone());
        Some(item.unwrap_or(serde_json::json!({})))
    } else {
        None
    }
}

fn proto_type_of(
    node: &JVal,
    defs: Option<&serde_json::Map<String, JVal>>,
    field_name: &str,
    nested: &mut Vec<MessageDef>,
) -> (u64, Option<String>) {
    let node = resolve(node, defs);

    // Option<T>: collapse anyOf [T, null] to T.
    if let Some(alts) = node
        .get("anyOf")
        .or_else(|| node.get("oneOf"))
        .and_then(JVal::as_array)
    {
        let non_null: Vec<&JVal> = alts
            .iter()
            .filter(|a| json_type(a) != Some("null"))
            .collect();
        if let [single] = non_null.as_slice() {
            return proto_type_of(single, defs, field_name, nested);
        }
        // Multi-branch union: JSON-encoded string.
        return (T_STRING, None);
    }

    match json_type(node) {
        Some("string") => (T_STRING, None),
        Some("integer") => (T_INT64, None),
        Some("number") => (T_DOUBLE, None),
        Some("boolean") => (T_BOOL, None),
        Some("object") if node.get("properties").is_some() => {
            let msg_name = format!("{}Msg", pascal_case(field_name));
            let def = build_message(&msg_name, node, defs);
            nested.push(def);
            (T_MESSAGE, Some(msg_name))
        }
        // enum / free-form object / any -> JSON-encoded string
        _ => (T_STRING, None),
    }
}

fn resolve<'a>(node: &'a JVal, defs: Option<&'a serde_json::Map<String, JVal>>) -> &'a JVal {
    if let (Some(r), Some(d)) = (node.get("$ref").and_then(JVal::as_str), defs) {
        if let Some(key) = r.rsplit('/').next() {
            if let Some(target) = d.get(key) {
                return resolve(target, defs);
            }
        }
    }
    node
}

fn json_type(node: &JVal) -> Option<&str> {
    match node.get("type") {
        Some(JVal::String(s)) => Some(s.as_str()),
        Some(JVal::Array(a)) => a.iter().filter_map(JVal::as_str).find(|t| *t != "null"),
        _ => None,
    }
}

fn collect_nested_symbols(msg: &MessageDef, full: &str, out: &mut Vec<String>) {
    for n in &msg.nested {
        let child = format!("{full}.{}", n.name);
        out.push(child.clone());
        collect_nested_symbols(n, &child, out);
    }
}

// ---------------------------------------------------------------------------
// descriptor.proto wire encoding
// ---------------------------------------------------------------------------

fn encode_message(def: &MessageDef) -> Vec<u8> {
    // DescriptorProto: name=1, field=2, nested_type=3
    let mut out = Vec::new();
    put_str(&mut out, 1, &def.name);
    for f in &def.fields {
        // FieldDescriptorProto: name=1, number=3, label=4, type=5, type_name=6, json_name=10
        let mut fd = Vec::new();
        put_str(&mut fd, 1, &f.name);
        put_varint_field(&mut fd, 3, f.number);
        put_varint_field(&mut fd, 4, if f.repeated { L_REPEATED } else { L_OPTIONAL });
        put_varint_field(&mut fd, 5, f.proto_type);
        if let Some(t) = &f.type_name {
            // Relative reference resolves against the enclosing scope.
            put_str(&mut fd, 6, t);
        }
        put_str(&mut fd, 10, &json_name(&f.name));
        put_bytes(&mut out, 2, &fd);
    }
    for n in &def.nested {
        put_bytes(&mut out, 3, &encode_message(n));
    }
    out
}

fn put_varint(out: &mut Vec<u8>, mut v: u64) {
    loop {
        let b = (v & 0x7f) as u8;
        v >>= 7;
        if v == 0 {
            out.push(b);
            break;
        }
        out.push(b | 0x80);
    }
}

fn put_tag(out: &mut Vec<u8>, field: u32, wire: u8) {
    put_varint(out, ((field as u64) << 3) | wire as u64);
}

fn put_varint_field(out: &mut Vec<u8>, field: u32, v: u64) {
    put_tag(out, field, 0);
    put_varint(out, v);
}

fn put_str(out: &mut Vec<u8>, field: u32, s: &str) {
    put_bytes(out, field, s.as_bytes());
}

fn put_bytes(out: &mut Vec<u8>, field: u32, b: &[u8]) {
    put_tag(out, field, 2);
    put_varint(out, b.len() as u64);
    out.extend_from_slice(b);
}

fn json_name(snake: &str) -> String {
    let mut out = String::new();
    let mut upper = false;
    for c in snake.chars() {
        if c == '_' {
            upper = true;
        } else if upper {
            out.extend(c.to_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    out
}

pub fn pascal_case(s: &str) -> String {
    let mut out = String::new();
    let mut upper = true;
    for c in s.chars() {
        if c == '_' || c == '-' || c == '.' {
            upper = true;
        } else if upper {
            out.extend(c.to_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    out
}

pub fn snake_case(s: &str) -> String {
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() {
            if i > 0 && !out.ends_with('_') {
                out.push('_');
            }
            out.extend(c.to_lowercase());
        } else if c == '-' || c == '.' {
            out.push('_');
        } else {
            out.push(c);
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Minimal FileDescriptorSet decoding — enough for reflection indexing,
// catalog `file_by_filename`, and tests. Returns borrowed subslices of the
// input (zero-copy).
// ---------------------------------------------------------------------------

/// Summary of one file entry inside an encoded `FileDescriptorSet`, borrowing
/// the underlying descriptor bytes.
#[derive(Debug)]
pub struct FileSummary<'a> {
    pub name: String,
    pub package: String,
    pub messages: Vec<String>,
    pub services: Vec<String>,
    /// Borrowed `FileDescriptorProto` bytes within the set.
    pub bytes: &'a [u8],
}

/// Iterate the `file` entries of an encoded `FileDescriptorSet`.
pub fn decode_file_summaries(set: &[u8]) -> Result<Vec<FileSummary<'_>>, String> {
    let mut out = Vec::new();
    let mut r = Reader { buf: set, pos: 0 };
    while !r.done() {
        let (field, wire) = r.tag()?;
        if field == 1 && wire == 2 {
            let bytes = r.len_delim()?;
            out.push(decode_file_summary(bytes)?);
        } else {
            r.skip(wire)?;
        }
    }
    Ok(out)
}

fn decode_file_summary(bytes: &[u8]) -> Result<FileSummary<'_>, String> {
    let mut s = FileSummary {
        name: String::new(),
        package: String::new(),
        messages: Vec::new(),
        services: Vec::new(),
        bytes,
    };
    let mut r = Reader { buf: bytes, pos: 0 };
    while !r.done() {
        let (field, wire) = r.tag()?;
        match (field, wire) {
            (1, 2) => s.name = r.string()?,
            (2, 2) => s.package = r.string()?,
            (4, 2) => s.messages.push(first_string_field(r.len_delim()?)?),
            (6, 2) => s.services.push(first_string_field(r.len_delim()?)?),
            _ => r.skip(wire)?,
        }
    }
    Ok(s)
}

/// Read field #1 (name) of a DescriptorProto/ServiceDescriptorProto.
fn first_string_field(bytes: &[u8]) -> Result<String, String> {
    let mut r = Reader { buf: bytes, pos: 0 };
    while !r.done() {
        let (field, wire) = r.tag()?;
        if field == 1 && wire == 2 {
            return r.string();
        }
        r.skip(wire)?;
    }
    Ok(String::new())
}

struct Reader<'a> {
    buf: &'a [u8],
    pos: usize,
}

impl<'a> Reader<'a> {
    fn done(&self) -> bool {
        self.pos >= self.buf.len()
    }

    fn varint(&mut self) -> Result<u64, String> {
        let mut v = 0u64;
        let mut shift = 0;
        loop {
            let b = *self
                .buf
                .get(self.pos)
                .ok_or_else(|| "varint overruns buffer".to_string())?;
            self.pos += 1;
            v |= ((b & 0x7f) as u64) << shift;
            if b & 0x80 == 0 {
                return Ok(v);
            }
            shift += 7;
            if shift > 63 {
                return Err("varint too long".into());
            }
        }
    }

    fn tag(&mut self) -> Result<(u32, u8), String> {
        let t = self.varint()?;
        Ok(((t >> 3) as u32, (t & 7) as u8))
    }

    fn len_delim(&mut self) -> Result<&'a [u8], String> {
        let len = self.varint()? as usize;
        let end = self.pos + len;
        if end > self.buf.len() {
            return Err("length-delimited field overruns buffer".into());
        }
        let s = &self.buf[self.pos..end];
        self.pos = end;
        Ok(s)
    }

    fn string(&mut self) -> Result<String, String> {
        Ok(String::from_utf8_lossy(self.len_delim()?).into_owned())
    }

    fn skip(&mut self, wire: u8) -> Result<(), String> {
        match wire {
            0 => {
                self.varint()?;
            }
            1 => self.pos += 8,
            2 => {
                self.len_delim()?;
            }
            5 => self.pos += 4,
            w => return Err(format!("unsupported wire type {w}")),
        }
        if self.pos > self.buf.len() {
            return Err("skip overruns buffer".into());
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::adapter::{method_decl_from_schemars_with_output, AckOutput};
    use crate::schema::SideEffect;
    use serde::{Deserialize, Serialize};

    #[derive(Serialize, Deserialize, schemars::JsonSchema)]
    struct SetDeviceInput {
        interface: String,
        private_key: String,
        listen_port: Option<u16>,
        fwmark: Option<u32>,
    }

    #[test]
    fn typed_descriptor_matches_spec_naming() {
        let decl = method_decl_from_schemars_with_output::<SetDeviceInput, AckOutput>(
            "set_device",
            SideEffect::Mutation,
            false,
            "wireguard.write",
            "mut.network.wireguard.set-device@v1",
        );
        let d = method_file_descriptor("wireguard", &decl);
        assert_eq!(d.package, "operation.method.wireguard.set_device");
        assert_eq!(
            d.service_full,
            "operation.method.wireguard.set_device.SetDeviceService"
        );
        assert_eq!(
            d.input_full,
            "operation.method.wireguard.set_device.SetDeviceInput"
        );
        assert_eq!(d.grpc_path, "/operation.method.wireguard.set_device.SetDeviceService/SetDevice");

        // Round-trip through the wire decoder: real typed messages, no Struct.
        let mut set = Vec::new();
        put_bytes(&mut set, 1, &d.file_descriptor_proto);
        let files = decode_file_summaries(&set).unwrap();
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].name, "operation/method/wireguard/set_device.proto");
        assert_eq!(files[0].services, vec!["SetDeviceService"]);
        assert_eq!(
            files[0].messages,
            vec!["SetDeviceInput", "SetDeviceOutput"]
        );
    }

    #[test]
    fn case_conversions() {
        assert_eq!(pascal_case("set_device"), "SetDevice");
        assert_eq!(snake_case("SetDevice"), "set_device");
        assert_eq!(json_name("listen_port"), "listenPort");
    }
}

//! `PluginObjectBlob` — the sealed, self-describing projection of one
//! `PluginSchema` into one runtime identity (whitepaper "Target Data Model").
//!
//! The blob couples the four identities that must not drift:
//! schema identity (canonical JSON + sha256), D-Bus identity, gRPC identity,
//! and the reflection descriptor identity. It is deliberately redundant at the
//! blob boundary: schema stays authoritative, but the blob is self-describing
//! enough that reflection, GUI, compliance, and dispatch reason about the same
//! object without reassembling identity from scattered files.
//!
//! ## Sealed byte format (zero-copy)
//!
//! ```text
//! offset  size  content
//! 0       8     magic "OPBLOB01"
//! 8       2     format version (u16 LE) = 1
//! 10      2     section count (u16 LE)
//! 12      4     reserved
//! 16      32    sha256 of the SCHEMA_JSON section (the schema hash)
//! 48      16    reserved
//! 64      24*n  section table: tag u32, reserved u32, offset u64, len u64
//! ...           8-byte-aligned section payloads
//! ```
//!
//! Sections: 1 = canonical `PluginSchema` JSON, 2 = `BlobManifest` JSON,
//! 3 = protobuf `FileDescriptorSet`, 4 = compliance/extra metadata JSON.
//!
//! `BlobRef` verifies magic + hash once, then hands out borrowed slices —
//! reads never copy or re-parse the payload. Sealed bytes are fully
//! deterministic for the same schema (sorted maps, no timestamps), so the
//! schema hash doubles as the artifact identity in the filename:
//! `<plugin_id>.<hash16>.blob`.

use crate::descriptor;
use crate::schema::{hex, PluginSchema, SideEffect};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::io;
use std::path::{Path, PathBuf};

pub const MAGIC: &[u8; 8] = b"OPBLOB01";
pub const FORMAT_VERSION: u16 = 1;

pub const SECTION_SCHEMA_JSON: u32 = 1;
pub const SECTION_MANIFEST_JSON: u32 = 2;
pub const SECTION_DESCRIPTOR_SET: u32 = 3;
pub const SECTION_META_JSON: u32 = 4;

const HEADER_LEN: usize = 64;
const SECTION_ENTRY_LEN: usize = 24;

/// D-Bus identity carried by the blob (REQ-7.1/7.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DbusIdentity {
    pub bus_name: String,
    pub object_path: String,
    pub interface_name: String,
}

/// gRPC identity: per-method packages/services synthesized from the schema.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct GrpcIdentity {
    /// Fully-qualified service names, sorted.
    pub services: Vec<String>,
    /// Descriptor file names, sorted (parallel to services).
    pub files: Vec<String>,
}

/// Per-method manifest entry copied from `PluginSchema.methods` plus the
/// synthesized gRPC identity — the compliance/audit unit.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MethodManifest {
    pub schema_name: String,
    pub grpc_name: String,
    pub grpc_path: String,
    pub grpc_service: String,
    pub grpc_file: String,
    pub input_message: String,
    pub output_message: String,
    pub subid: String,
    pub required_capability: Option<String>,
    pub side_effect: SideEffect,
    pub idempotent: bool,
    /// Fully-qualified symbols the method's descriptor file defines.
    pub symbols: Vec<String>,
}

/// The blob's self-describing metadata (section 2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct BlobManifest {
    pub plugin_id: String,
    pub schema_version: String,
    pub schema_hash: String,
    pub dbus: DbusIdentity,
    pub grpc: GrpcIdentity,
    /// WireGuard-keypair identity of the publishing account (public half
    /// only); its session persists for the life of the account.
    #[serde(default)]
    pub identity: Option<crate::identity::BlobIdentity>,
    pub methods: Vec<MethodManifest>,
}

/// Owned, unsealed blob. `seal()` produces the immutable byte image.
#[derive(Debug, Clone)]
pub struct PluginObjectBlob {
    pub manifest: BlobManifest,
    /// Canonical `PluginSchema` JSON (the authoritative contract bytes).
    pub schema_json: String,
    /// Encoded `google.protobuf.FileDescriptorSet` for all plugin methods.
    pub descriptor_set: Vec<u8>,
    /// Compliance / extra metadata (subids, immutable paths, dialect …).
    pub meta_json: String,
}

/// Canonical D-Bus path form: lowercase, hyphens -> underscores.
pub fn canonical_plugin_id(name: &str) -> String {
    name.to_lowercase().replace('-', "_")
}

/// Freeze one `PluginSchema` into a `PluginObjectBlob` (whitepaper "Blob
/// Creation Pipeline" steps 3–9). The schema is the input and stays the
/// authority; nothing here invents contract data.
pub fn blobify(schema: &PluginSchema) -> PluginObjectBlob {
    blobify_with_identity(schema, None)
}

/// `blobify`, stamping the publishing account's WireGuard-keypair identity
/// (public half only) into the manifest.
pub fn blobify_with_identity(
    schema: &PluginSchema,
    identity: Option<crate::identity::BlobIdentity>,
) -> PluginObjectBlob {
    let plugin_id = canonical_plugin_id(&schema.name);
    let schema_json = schema.canonical_json();
    let schema_hash = {
        let mut h = Sha256::new();
        h.update(schema_json.as_bytes());
        hex(&h.finalize())
    };

    let (descriptor_set, method_infos) = descriptor::descriptor_set_for_plugin(&plugin_id, schema);

    let mut methods: Vec<MethodManifest> = method_infos
        .iter()
        .map(|d| {
            let decl = &schema.methods[&d.method_name];
            MethodManifest {
                schema_name: decl.name.clone(),
                grpc_name: descriptor::pascal_case(&decl.name),
                grpc_path: d.grpc_path.clone(),
                grpc_service: d.service_full.clone(),
                grpc_file: d.file_name.clone(),
                input_message: d.input_full.clone(),
                output_message: d.output_full.clone(),
                subid: decl.subid.clone(),
                required_capability: decl.required_capability.clone(),
                side_effect: decl.side_effect,
                idempotent: decl.idempotent,
                symbols: d.symbols.clone(),
            }
        })
        .collect();
    methods.sort_by(|a, b| a.schema_name.cmp(&b.schema_name));

    let mut services: Vec<String> = methods.iter().map(|m| m.grpc_service.clone()).collect();
    services.sort();
    let mut files: Vec<String> = methods.iter().map(|m| m.grpc_file.clone()).collect();
    files.sort();

    let manifest = BlobManifest {
        plugin_id: plugin_id.clone(),
        schema_version: schema.version.clone(),
        schema_hash,
        dbus: DbusIdentity {
            bus_name: "org.opdbus.v1.plugins".to_string(),
            object_path: format!("/org/opdbus/v1/plugins/{plugin_id}"),
            interface_name: "org.opdbus.v1.Plugin".to_string(),
        },
        grpc: GrpcIdentity { services, files },
        identity,
        methods,
    };

    let meta = serde_json::json!({
        "blob_format": FORMAT_VERSION,
        "dialect": schema.dialect,
        "subids": schema.subids,
        "immutable_paths": schema.immutable_paths,
        "json_schema": schema.to_json_schema(),
    });

    PluginObjectBlob {
        manifest,
        schema_json,
        descriptor_set,
        meta_json: serde_json::to_string(&meta).expect("meta serializes"),
    }
}

impl PluginObjectBlob {
    /// Seal into the immutable byte image. Deterministic: same schema, same bytes.
    pub fn seal(&self) -> Vec<u8> {
        let manifest_json =
            serde_json::to_string(&serde_json::to_value(&self.manifest).unwrap()).unwrap();
        let sections: [(u32, &[u8]); 4] = [
            (SECTION_SCHEMA_JSON, self.schema_json.as_bytes()),
            (SECTION_MANIFEST_JSON, manifest_json.as_bytes()),
            (SECTION_DESCRIPTOR_SET, &self.descriptor_set),
            (SECTION_META_JSON, self.meta_json.as_bytes()),
        ];

        let table_len = sections.len() * SECTION_ENTRY_LEN;
        let mut offset = align8(HEADER_LEN + table_len);
        let mut entries = Vec::with_capacity(sections.len());
        for (tag, bytes) in &sections {
            entries.push((*tag, offset as u64, bytes.len() as u64));
            offset = align8(offset + bytes.len());
        }

        let mut out = Vec::with_capacity(offset);
        out.extend_from_slice(MAGIC);
        out.extend_from_slice(&FORMAT_VERSION.to_le_bytes());
        out.extend_from_slice(&(sections.len() as u16).to_le_bytes());
        out.extend_from_slice(&[0u8; 4]);
        let mut h = Sha256::new();
        h.update(self.schema_json.as_bytes());
        out.extend_from_slice(&h.finalize());
        out.extend_from_slice(&[0u8; 16]);
        debug_assert_eq!(out.len(), HEADER_LEN);

        for (tag, off, len) in &entries {
            out.extend_from_slice(&tag.to_le_bytes());
            out.extend_from_slice(&[0u8; 4]);
            out.extend_from_slice(&off.to_le_bytes());
            out.extend_from_slice(&len.to_le_bytes());
        }

        for ((_, bytes), (_, off, _)) in sections.iter().zip(&entries) {
            while out.len() < *off as usize {
                out.push(0);
            }
            out.extend_from_slice(bytes);
        }
        out
    }

    /// `<plugin_id>.<hash16>.blob` — hash-addressed filename (shm layout).
    pub fn file_name(&self) -> String {
        format!(
            "{}.{}.blob",
            self.manifest.plugin_id,
            &self.manifest.schema_hash[..16]
        )
    }

    pub fn write_to_dir(&self, dir: &Path) -> io::Result<PathBuf> {
        std::fs::create_dir_all(dir)?;
        let path = dir.join(self.file_name());
        std::fs::write(&path, self.seal())?;
        Ok(path)
    }
}

fn align8(n: usize) -> usize {
    (n + 7) & !7
}

/// Zero-copy view over sealed blob bytes. Construction verifies magic,
/// bounds, and the schema hash once; accessors return borrowed slices.
pub struct BlobRef<'a> {
    bytes: &'a [u8],
    sections: Vec<(u32, usize, usize)>,
}

impl<'a> BlobRef<'a> {
    pub fn new(bytes: &'a [u8]) -> Result<Self, String> {
        if bytes.len() < HEADER_LEN || &bytes[..8] != MAGIC {
            return Err("not an OPBLOB01 blob".into());
        }
        let version = u16::from_le_bytes([bytes[8], bytes[9]]);
        if version != FORMAT_VERSION {
            return Err(format!("unsupported blob format version {version}"));
        }
        let count = u16::from_le_bytes([bytes[10], bytes[11]]) as usize;
        let table_end = HEADER_LEN + count * SECTION_ENTRY_LEN;
        if bytes.len() < table_end {
            return Err("section table overruns blob".into());
        }
        let mut sections = Vec::with_capacity(count);
        for i in 0..count {
            let e = HEADER_LEN + i * SECTION_ENTRY_LEN;
            let tag = u32::from_le_bytes(bytes[e..e + 4].try_into().unwrap());
            let off = u64::from_le_bytes(bytes[e + 8..e + 16].try_into().unwrap()) as usize;
            let len = u64::from_le_bytes(bytes[e + 16..e + 24].try_into().unwrap()) as usize;
            if off + len > bytes.len() {
                return Err(format!("section {tag} overruns blob"));
            }
            sections.push((tag, off, len));
        }
        let blob = Self { bytes, sections };

        // Verify schema hash (blob-drift guard).
        let schema = blob
            .section(SECTION_SCHEMA_JSON)
            .ok_or("missing schema section")?;
        let mut h = Sha256::new();
        h.update(schema);
        if h.finalize().as_slice() != &bytes[16..48] {
            return Err("schema hash mismatch: blob is corrupt or tampered".into());
        }
        Ok(blob)
    }

    fn section(&self, tag: u32) -> Option<&'a [u8]> {
        self.sections
            .iter()
            .find(|(t, _, _)| *t == tag)
            .map(|(_, off, len)| &self.bytes[*off..*off + *len])
    }

    /// Canonical `PluginSchema` JSON — borrowed, zero-copy.
    pub fn schema_json(&self) -> &'a str {
        std::str::from_utf8(self.section(SECTION_SCHEMA_JSON).unwrap())
            .expect("schema section is UTF-8")
    }

    pub fn manifest_json(&self) -> &'a str {
        std::str::from_utf8(self.section(SECTION_MANIFEST_JSON).unwrap())
            .expect("manifest section is UTF-8")
    }

    /// Encoded `FileDescriptorSet` — borrowed, zero-copy; slices of this can
    /// be served directly to reflection clients.
    pub fn descriptor_set(&self) -> &'a [u8] {
        self.section(SECTION_DESCRIPTOR_SET).unwrap_or(&[])
    }

    pub fn meta_json(&self) -> Option<&'a str> {
        self.section(SECTION_META_JSON)
            .and_then(|b| std::str::from_utf8(b).ok())
    }

    pub fn schema_hash_hex(&self) -> String {
        hex(&self.bytes[16..48])
    }

    /// Parse the manifest (the one intentional allocation on the read path;
    /// everything else stays borrowed).
    pub fn manifest(&self) -> Result<BlobManifest, String> {
        serde_json::from_str(self.manifest_json()).map_err(|e| format!("manifest parse: {e}"))
    }

    /// Reconstruct the authoritative `PluginSchema` from the sealed bytes.
    pub fn plugin_schema(&self) -> Result<PluginSchema, String> {
        serde_json::from_str(self.schema_json()).map_err(|e| format!("schema parse: {e}"))
    }
}

//! `PluginSchema` — the published single source of truth for a plugin's
//! contract. Faithful port of the shapes in
//! `op-plugins/src/state_plugins/schemars_adapter.rs` and the spec's Layer 2
//! (`op-state-store/src/plugin_schema.rs`), reduced to what the blob pipeline
//! needs and using `serde_json::Value` for embedded schema documents.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::collections::HashMap;

pub const DIALECT_2020_12: &str = "https://json-schema.org/draft/2020-12/schema";

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum FieldType {
    String,
    Integer,
    Float,
    Boolean,
    Any,
    Enum(Vec<String>),
    /// Discriminated union (schemars `anyOf`/`oneOf` with >1 non-null branch).
    OneOf(Vec<FieldType>),
    Array(Box<FieldType>),
    Object(HashMap<String, FieldSchema>),
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Constraint {
    Min { value: f64 },
    Max { value: f64 },
    Pattern { regex: String },
    OneOf { values: Vec<Value> },
    RequiresField { field: String },
    Custom { validator: String },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FieldSchema {
    pub field_type: FieldType,
    pub required: bool,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub default: Option<Value>,
    #[serde(default)]
    pub example: Option<Value>,
    #[serde(default)]
    pub constraints: Vec<Constraint>,
    #[serde(default)]
    pub read_only: bool,
    #[serde(default)]
    pub read_only_when: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SideEffect {
    Read,
    Mutation,
    External,
}

/// A method declaration. `args`/`returns` are full JSON Schema 2020-12
/// documents produced by `schemars::schema_for!` on the input/output structs.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MethodDecl {
    pub name: String,
    pub args: Value,
    /// Always `Some` for spec-compliant plugins (REQ-4.4): success/failure-only
    /// methods return `AckOutput`.
    pub returns: Option<Value>,
    pub side_effect: SideEffect,
    pub idempotent: bool,
    pub required_capability: Option<String>,
    /// OSCAL subid, e.g. `mut.network.wireguard.peer-add@v1`.
    pub subid: String,
}

/// The published contract object. Consumers read this — never raw schemars
/// output (spec Key Decision 2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PluginSchema {
    pub name: String,
    pub version: String,
    pub description: String,
    /// From `adapter::plugin_schema_from_json` (schemars-derived state struct).
    pub fields: HashMap<String, FieldSchema>,
    /// Set imperatively in the plugin's schema function.
    pub methods: HashMap<String, MethodDecl>,
    /// From `x-oscal-subid` annotations; `__schema__` is the schema-level subid.
    pub subids: HashMap<String, String>,
    /// From struct-level `x-immutable-paths`.
    pub immutable_paths: Vec<String>,
    pub dialect: String,
}

impl PluginSchema {
    pub fn builder(name: &str) -> PluginSchemaBuilder {
        PluginSchemaBuilder {
            name: name.to_string(),
            version: "1.0.0".to_string(),
            description: String::new(),
            methods: HashMap::new(),
        }
    }

    /// Deterministic canonical JSON of the whole contract. serde_json's Map is
    /// BTreeMap-backed (no `preserve_order` feature), so object keys serialize
    /// sorted; HashMaps pass through `to_value` into sorted maps.
    pub fn canonical_json(&self) -> String {
        let v = serde_json::to_value(self).expect("PluginSchema serializes cleanly");
        serde_json::to_string(&v).expect("canonical value serializes")
    }

    /// sha256 over `canonical_json` — the blob identity hash.
    pub fn schema_hash(&self) -> [u8; 32] {
        let mut h = Sha256::new();
        h.update(self.canonical_json().as_bytes());
        h.finalize().into()
    }

    pub fn schema_hash_hex(&self) -> String {
        hex(&self.schema_hash())
    }

    /// Render the state contract as a JSON Schema 2020-12 document — the shape
    /// consumers of `live-schema.json` (and now blob readers) see.
    pub fn to_json_schema(&self) -> Value {
        let mut props = serde_json::Map::new();
        let mut required = Vec::new();
        let mut names: Vec<&String> = self.fields.keys().collect();
        names.sort();
        for name in names {
            let f = &self.fields[name];
            if f.required {
                required.push(Value::String(name.clone()));
            }
            let mut node = field_to_json_schema(f);
            if let Some(subid) = self.subids.get(name) {
                node.as_object_mut()
                    .unwrap()
                    .insert("x-oscal-subid".into(), Value::String(subid.clone()));
            }
            props.insert(name.clone(), node);
        }
        let mut root = serde_json::Map::new();
        root.insert("$schema".into(), Value::String(self.dialect.clone()));
        root.insert("title".into(), Value::String(self.name.clone()));
        root.insert("description".into(), Value::String(self.description.clone()));
        root.insert("type".into(), Value::String("object".into()));
        root.insert("properties".into(), Value::Object(props));
        if !required.is_empty() {
            root.insert("required".into(), Value::Array(required));
        }
        if let Some(subid) = self.subids.get("__schema__") {
            root.insert("x-oscal-subid".into(), Value::String(subid.clone()));
        }
        if !self.immutable_paths.is_empty() {
            root.insert(
                "x-immutable-paths".into(),
                Value::Array(
                    self.immutable_paths
                        .iter()
                        .map(|p| Value::String(p.clone()))
                        .collect(),
                ),
            );
        }
        root.insert("x-plugin-version".into(), Value::String(self.version.clone()));
        Value::Object(root)
    }
}

pub struct PluginSchemaBuilder {
    name: String,
    version: String,
    description: String,
    methods: HashMap<String, MethodDecl>,
}

impl PluginSchemaBuilder {
    pub fn version(mut self, v: &str) -> Self {
        self.version = v.to_string();
        self
    }

    pub fn description(mut self, d: &str) -> Self {
        self.description = d.to_string();
        self
    }

    /// Task 0.2 convenience: chainable method registration.
    pub fn method(mut self, decl: MethodDecl) -> Self {
        self.methods.insert(decl.name.clone(), decl);
        self
    }

    pub fn build(self) -> PluginSchema {
        PluginSchema {
            name: self.name,
            version: self.version,
            description: self.description,
            fields: HashMap::new(),
            methods: self.methods,
            subids: HashMap::new(),
            immutable_paths: Vec::new(),
            dialect: DIALECT_2020_12.to_string(),
        }
    }
}

fn field_to_json_schema(f: &FieldSchema) -> Value {
    let mut node = type_to_json_schema(&f.field_type);
    let obj = node.as_object_mut().unwrap();
    if !f.description.is_empty() {
        obj.insert("description".into(), Value::String(f.description.clone()));
    }
    if let Some(d) = &f.default {
        obj.insert("default".into(), d.clone());
    }
    if let Some(e) = &f.example {
        obj.insert("examples".into(), Value::Array(vec![e.clone()]));
    }
    if f.read_only {
        obj.insert("readOnly".into(), Value::Bool(true));
    }
    for c in &f.constraints {
        match c {
            Constraint::Min { value } => {
                obj.insert("minimum".into(), serde_json::json!(value));
            }
            Constraint::Max { value } => {
                obj.insert("maximum".into(), serde_json::json!(value));
            }
            Constraint::Pattern { regex } => {
                obj.insert("pattern".into(), Value::String(regex.clone()));
            }
            _ => {}
        }
    }
    node
}

fn type_to_json_schema(t: &FieldType) -> Value {
    match t {
        FieldType::String => serde_json::json!({"type": "string"}),
        FieldType::Integer => serde_json::json!({"type": "integer"}),
        FieldType::Float => serde_json::json!({"type": "number"}),
        FieldType::Boolean => serde_json::json!({"type": "boolean"}),
        FieldType::Any => serde_json::json!({}),
        FieldType::Enum(vs) => serde_json::json!({"type": "string", "enum": vs}),
        FieldType::OneOf(branches) => {
            serde_json::json!({"oneOf": branches.iter().map(type_to_json_schema).collect::<Vec<_>>()})
        }
        FieldType::Array(inner) => {
            serde_json::json!({"type": "array", "items": type_to_json_schema(inner)})
        }
        FieldType::Object(map) => {
            let mut props = serde_json::Map::new();
            let mut required = Vec::new();
            let mut names: Vec<&String> = map.keys().collect();
            names.sort();
            for name in names {
                let f = &map[name];
                if f.required {
                    required.push(Value::String(name.clone()));
                }
                props.insert(name.clone(), field_to_json_schema(f));
            }
            let mut node = serde_json::Map::new();
            node.insert("type".into(), Value::String("object".into()));
            node.insert("properties".into(), Value::Object(props));
            if !required.is_empty() {
                node.insert("required".into(), Value::Array(required));
            }
            Value::Object(node)
        }
    }
}

pub fn hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push_str(&format!("{b:02x}"));
    }
    s
}

//! # op-blob — schema-driven plugin object blobs
//!
//! Implements the pipeline defined in
//! `.kiro/specs/schemars-to-reflection-plugin-pipeline/` and the
//! schema-coupled-plugin-blob-reflection whitepaper:
//!
//! ```text
//! Rust state/input/output structs (#[derive(schemars::JsonSchema)])
//!   -> schemars JSON Schema 2020-12
//!   -> adapter::plugin_schema_from_json
//!   -> PluginSchema                      <- SINGLE SOURCE OF TRUTH
//!   -> blob::blobify
//!   -> PluginObjectBlob                  <- sealed projection: schema + metadata
//!        schema_json + schema_hash
//!        D-Bus identity (/org/opdbus/v1/plugins/<name>)
//!        gRPC identity + FileDescriptorSet (typed, per-method)
//!        method manifest (subid, capability, side_effect, idempotent)
//!   -> catalog::ActiveReflectionCatalog  <- /dev/shm/opdbus/plugin-blobs/<id>.<hash>.blob
//!   -> btrfs::seal_blobs_into_btrfs_image <- btrfs filesystem in the blob artifact
//! ```
//!
//! Non-negotiable rules carried over from the whitepaper:
//! 1. `PluginSchema` is the source of truth. The blob is a frozen projection,
//!    never a second source.
//! 2. The plugin owns its schema; schemars is the derivation tool, not the
//!    published contract.
//! 3. Blobs are per-object artifacts (one plugin, one blob, one schema hash),
//!    replacing the monolithic `/dev/shm/live-schema.json` runtime shape.
//! 4. Reflection advertises only active blobs; descriptors are synthesized
//!    from `MethodDecl.args/returns` — no phantom services.
//! 5. Zero-copy: a sealed blob is a sectioned byte image; `BlobRef` hands out
//!    borrowed slices (schema JSON, manifest, descriptor bytes) without
//!    re-parsing or re-allocating on the read path.
//!
//! Divergences from the full workspace (documented, deliberate):
//! - `PluginSchema` here is a faithful but reduced port of
//!   `op-state-store::plugin_schema` (this repo does not contain that crate).
//!   Values use `serde_json::Value` instead of `simd_json::OwnedValue`.
//! - Descriptor bytes are hand-encoded protobuf (`descriptor.rs`) instead of
//!   prost — keeps the crate dependency-free per NFR-3's spirit.

pub mod adapter;
pub mod blob;
pub mod btrfs;
pub mod catalog;
pub mod demo;
pub mod descriptor;
pub mod identity;
pub mod schema;
pub mod subid;

pub use adapter::{
    apply_state_defaults, method_decl_from_schemars_with_output, plugin_schema_from_json,
    schema_diffs, AckOutput, EmptyInput,
};
pub use blob::{
    blobify, blobify_with_identity, BlobManifest, BlobRef, DbusIdentity, GrpcIdentity,
    PluginObjectBlob,
};
pub use catalog::ActiveReflectionCatalog;
pub use identity::{BlobIdentity, WgKeypair};
pub use schema::{Constraint, FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
pub use subid::validate_subid;

//! Generic plugin object blob support.
//!
//! A blob is the sealed projection of one plugin schema into the callable
//! gRPC surface. It carries the D-Bus identity, the canonical schema bytes,
//! the callable descriptor bytes, the method manifest copied from
//! `PluginSchema.methods`, and (optionally) the publishing account's
//! WireGuard-keypair identity.
//!
//! Ported verbatim from `op-grpc-bridge::plugin_object_blob` (first pass) so
//! this crate is a drop-in replacement; additions are `identity`, `seal()` /
//! `from_sealed()` (see [`crate::sealed`]), and the shm [`crate::store`].

use op_state_store::PluginSchema;
use prost::Message;
use prost_types::{
    field_descriptor_proto, DescriptorProto, FieldDescriptorProto, FileDescriptorProto,
    FileDescriptorSet, MethodDescriptorProto, ServiceDescriptorProto,
};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

pub const OBJECT_BLOB_SHM_DIR: &str = "/dev/shm/opdbus/plugin-blobs";

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PluginObjectBlob {
    pub plugin_id: String,
    pub schema_version: String,
    pub schema_hash: String,
    pub schema_json: Vec<u8>,
    pub dbus: DbusObjectIdentity,
    pub grpc: GrpcObjectIdentity,
    /// WireGuard-keypair identity of the publishing account (public half
    /// only); its session persists for the life of the account.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub identity: Option<crate::identity::BlobIdentity>,
    pub methods: Vec<BlobMethod>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DbusObjectIdentity {
    pub bus_name: String,
    pub object_path: String,
    pub interface_name: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GrpcObjectIdentity {
    pub package: String,
    pub service_name: String,
    pub descriptor_set: Vec<u8>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BlobMethod {
    pub schema_name: String,
    pub grpc_name: String,
    pub grpc_path: String,
    pub subid: String,
    pub required_capability: Option<String>,
    pub side_effect: String,
    pub idempotent: bool,
    pub args_schema: Vec<u8>,
    pub returns_schema: Vec<u8>,
}

pub fn blobify_plugin_schema(
    plugin_id: &str,
    schema: PluginSchema,
    dbus: DbusObjectIdentity,
    grpc_package: &str,
    grpc_service_name: &str,
) -> PluginObjectBlob {
    blobify_plugin_schema_with_identity(plugin_id, schema, dbus, grpc_package, grpc_service_name, None)
}

/// `blobify_plugin_schema`, stamping the publishing account's WG-keypair
/// identity (public half only) into the blob.
pub fn blobify_plugin_schema_with_identity(
    plugin_id: &str,
    schema: PluginSchema,
    dbus: DbusObjectIdentity,
    grpc_package: &str,
    grpc_service_name: &str,
    identity: Option<crate::identity::BlobIdentity>,
) -> PluginObjectBlob {
    let schema_json = canonical_schema_bytes(&schema);
    let schema_hash = sha256_hex(&schema_json);
    let mut methods = schema
        .methods
        .values()
        .map(|method| BlobMethod {
            schema_name: method.name.clone(),
            grpc_name: to_pascal_ident(&method.name),
            grpc_path: format!(
                "/{}/{}/{}",
                grpc_package,
                grpc_service_name
                    .rsplit('.')
                    .next()
                    .unwrap_or(grpc_service_name),
                to_pascal_ident(&method.name)
            ),
            subid: method.subid.clone(),
            required_capability: method.required_capability.clone(),
            side_effect: format!("{:?}", method.side_effect),
            idempotent: method.idempotent,
            args_schema: canonical_simd_bytes(&method.args),
            returns_schema: method
                .returns
                .as_ref()
                .map(canonical_simd_bytes)
                .unwrap_or_else(|| b"{}".to_vec()),
        })
        .collect::<Vec<_>>();
    methods.sort_by(|left, right| left.schema_name.cmp(&right.schema_name));

    PluginObjectBlob {
        plugin_id: plugin_id.to_string(),
        schema_version: schema.version.clone(),
        schema_hash,
        schema_json,
        dbus,
        grpc: GrpcObjectIdentity {
            package: grpc_package.to_string(),
            service_name: grpc_service_name.to_string(),
            descriptor_set: synthesize_plugin_descriptor_set(
                plugin_id,
                grpc_package,
                grpc_service_name,
                &schema,
            ),
        },
        identity,
        methods,
    }
}

pub fn synthesize_plugin_descriptor_set(
    plugin_id: &str,
    grpc_package: &str,
    grpc_service_name: &str,
    schema: &PluginSchema,
) -> Vec<u8> {
    let file = synthesize_plugin_file_descriptor(plugin_id, grpc_package, grpc_service_name, schema);
    let set = FileDescriptorSet { file: vec![file] };
    let mut bytes = Vec::new();
    if set.encode(&mut bytes).is_ok() {
        bytes
    } else {
        Vec::new()
    }
}

pub fn synthesize_plugin_file_descriptor(
    plugin_id: &str,
    grpc_package: &str,
    grpc_service_name: &str,
    schema: &PluginSchema,
) -> FileDescriptorProto {
    let service_short_name = grpc_service_name
        .rsplit('.')
        .next()
        .unwrap_or(grpc_service_name)
        .to_string();
    let mut methods = schema.methods.iter().collect::<Vec<_>>();
    methods.sort_by(|left, right| left.0.cmp(right.0));
    let message_prefix = to_pascal_ident(plugin_id);

    let mut message_type = Vec::new();
    let mut service_methods = Vec::new();

    for (method_name, method_decl) in methods {
        let rpc_name = to_pascal_ident(method_name);
        let input_name = format!("{message_prefix}{rpc_name}Request");
        let output_name = format!("{message_prefix}{rpc_name}Response");
        let empty_output = simd_json::json!({});
        let output_schema = method_decl.returns.as_ref().unwrap_or(&empty_output);

        message_type.push(schema_descriptor(&input_name, &method_decl.args));
        message_type.push(schema_descriptor(&output_name, output_schema));
        service_methods.push(MethodDescriptorProto {
            name: Some(rpc_name),
            input_type: Some(format!(".{grpc_package}.{input_name}")),
            output_type: Some(format!(".{grpc_package}.{output_name}")),
            client_streaming: Some(false),
            server_streaming: Some(false),
            ..Default::default()
        });
    }

    FileDescriptorProto {
        name: Some(format!(
            "operation/plugin/v1/{}.blob.proto",
            sanitize_proto_ident(plugin_id).to_lowercase()
        )),
        package: Some(grpc_package.to_string()),
        dependency: vec![
            "google/protobuf/struct.proto".to_string(),
            "google/protobuf/empty.proto".to_string(),
        ],
        message_type,
        service: vec![ServiceDescriptorProto {
            name: Some(service_short_name),
            method: service_methods,
            ..Default::default()
        }],
        syntax: Some("proto3".to_string()),
        ..Default::default()
    }
}

fn schema_descriptor(message_name: &str, schema: &simd_json::OwnedValue) -> DescriptorProto {
    let field = schema_fields(schema)
        .into_iter()
        .map(|field| {
            let (field_type, type_name) = field_descriptor_type(&field.proto_type);
            FieldDescriptorProto {
                name: Some(field.name.clone()),
                number: Some(field.number),
                label: Some(if field.repeated {
                    field_descriptor_proto::Label::Repeated
                } else {
                    field_descriptor_proto::Label::Optional
                } as i32),
                r#type: Some(field_type as i32),
                type_name,
                json_name: Some(field.json_name),
                ..Default::default()
            }
        })
        .collect();

    DescriptorProto {
        name: Some(to_pascal_ident(message_name)),
        field,
        ..Default::default()
    }
}

#[derive(Debug, Clone)]
struct ProtoField {
    name: String,
    json_name: String,
    proto_type: String,
    repeated: bool,
    number: i32,
}

fn schema_fields(schema: &simd_json::OwnedValue) -> Vec<ProtoField> {
    let Ok(json_schema) = serde_json::to_value(schema) else {
        return vec![fallback_field("payload", "google.protobuf.Value", false)];
    };

    let Some(properties) = json_schema.get("properties").and_then(|value| value.as_object()) else {
        return Vec::new();
    };

    let mut fields = properties.iter().collect::<Vec<_>>();
    fields.sort_by_key(|(name, _)| *name);

    fields
        .into_iter()
        .map(|(name, property)| {
            let (proto_type, repeated) = json_schema_type_to_proto(property);
            ProtoField {
                name: sanitize_proto_ident(name),
                json_name: name.clone(),
                proto_type,
                repeated,
                number: stable_field_number(name),
            }
        })
        .collect()
}

fn fallback_field(name: &str, proto_type: &str, repeated: bool) -> ProtoField {
    ProtoField {
        name: name.to_string(),
        json_name: name.to_string(),
        proto_type: proto_type.to_string(),
        repeated,
        number: stable_field_number(name),
    }
}

fn json_schema_type_to_proto(schema: &serde_json::Value) -> (String, bool) {
    if schema
        .get("enum")
        .and_then(|value| value.as_array())
        .is_some_and(|values| !values.is_empty())
    {
        return ("string".to_string(), false);
    }

    match schema.get("type") {
        Some(serde_json::Value::String(kind)) => match kind.as_str() {
            "string" => ("string".to_string(), false),
            "boolean" => ("bool".to_string(), false),
            "integer" => ("int64".to_string(), false),
            "number" => ("double".to_string(), false),
            "array" => {
                let item_type = schema
                    .get("items")
                    .map(|items| json_schema_type_to_proto(items).0)
                    .unwrap_or_else(|| "google.protobuf.Value".to_string());
                (item_type, true)
            }
            "object" => ("google.protobuf.Struct".to_string(), false),
            _ => ("google.protobuf.Value".to_string(), false),
        },
        Some(serde_json::Value::Array(kinds)) => {
            let first_non_null = kinds
                .iter()
                .filter_map(|value| value.as_str())
                .find(|kind| *kind != "null")
                .unwrap_or("object");
            json_schema_type_to_proto(&serde_json::json!({ "type": first_non_null }))
        }
        _ => {
            if schema.get("properties").is_some() {
                ("google.protobuf.Struct".to_string(), false)
            } else {
                ("google.protobuf.Value".to_string(), false)
            }
        }
    }
}

fn field_descriptor_type(proto_type: &str) -> (field_descriptor_proto::Type, Option<String>) {
    match proto_type {
        "string" => (field_descriptor_proto::Type::String, None),
        "bool" => (field_descriptor_proto::Type::Bool, None),
        "int64" => (field_descriptor_proto::Type::Int64, None),
        "double" => (field_descriptor_proto::Type::Double, None),
        "google.protobuf.Struct" => (
            field_descriptor_proto::Type::Message,
            Some(".google.protobuf.Struct".to_string()),
        ),
        "google.protobuf.Value" => (
            field_descriptor_proto::Type::Message,
            Some(".google.protobuf.Value".to_string()),
        ),
        _ => (
            field_descriptor_proto::Type::Message,
            Some(".google.protobuf.Value".to_string()),
        ),
    }
}

/// Deterministic proto field numbers derived from schema property names.
///
/// Uses FNV-1a over the original JSON property name, folds into the valid
/// protobuf range, and skips the reserved 19000-19999 block.
pub fn stable_field_number(name: &str) -> i32 {
    const FNV_OFFSET: u32 = 0x811c9dc5;
    const FNV_PRIME: u32 = 0x01000193;
    const MAX_FIELD: u32 = 536_870_911;
    const RESERVED_START: u32 = 19_000;
    const RESERVED_END: u32 = 19_999;

    let mut hash = FNV_OFFSET;
    for byte in name.as_bytes() {
        hash ^= u32::from(*byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }

    let mut number = (hash % MAX_FIELD).max(1);
    if (RESERVED_START..=RESERVED_END).contains(&number) {
        number += RESERVED_END - RESERVED_START + 1;
    }
    number as i32
}

impl PluginObjectBlob {
    pub fn method_count(&self) -> usize {
        self.methods.len()
    }

    /// Legacy JSON artifact name (first-pass format, kept for compatibility).
    pub fn shm_filename(&self) -> String {
        format!(
            "{}.{}.blob.json",
            sanitize_blob_component(&self.plugin_id),
            self.schema_hash
        )
    }

    pub fn shm_path(&self) -> String {
        format!("{}/{}", OBJECT_BLOB_SHM_DIR, self.shm_filename())
    }

    /// Hash-addressed sealed artifact name used by [`crate::store::BlobStore`].
    pub fn sealed_filename(&self) -> String {
        format!(
            "{}.{}.blob",
            sanitize_blob_component(&self.plugin_id),
            &self.schema_hash[..16.min(self.schema_hash.len())]
        )
    }

    /// Seal into the immutable zero-copy byte image (see [`crate::sealed`]).
    pub fn seal(&self) -> Vec<u8> {
        crate::sealed::seal(self)
    }

    /// Parse a sealed byte image back into an owned blob, verifying the
    /// schema hash.
    pub fn from_sealed(bytes: &[u8]) -> Result<Self, String> {
        crate::sealed::BlobRef::new(bytes)?.to_blob()
    }
}

pub fn canonical_schema_bytes(schema: &PluginSchema) -> Vec<u8> {
    let json = serde_json::to_vec(schema).unwrap_or_else(|_| b"{}".to_vec());
    let mut bytes = json.clone();
    let Ok(value) = simd_json::to_owned_value(&mut bytes) else {
        return json;
    };
    let canonical = op_state_store::schema_validator::canonicalize_json(&value);
    simd_json::to_vec(&canonical).unwrap_or(json)
}

pub fn canonical_simd_bytes(value: &simd_json::OwnedValue) -> Vec<u8> {
    let canonical = op_state_store::schema_validator::canonicalize_json(value);
    simd_json::to_vec(&canonical).unwrap_or_else(|_| b"{}".to_vec())
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    hex::encode(hasher.finalize())
}

pub fn to_pascal_ident(value: &str) -> String {
    let mut ident = String::new();
    let mut uppercase_next = true;
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() {
            if uppercase_next {
                ident.push(ch.to_ascii_uppercase());
                uppercase_next = false;
            } else {
                ident.push(ch);
            }
        } else {
            uppercase_next = true;
        }
    }
    if ident.is_empty() {
        "Generated".to_string()
    } else if ident.chars().next().is_some_and(|ch| ch.is_ascii_digit()) {
        format!("P{}", ident)
    } else {
        ident
    }
}

pub fn sanitize_blob_component(value: &str) -> String {
    let mut sanitized = String::new();
    let mut previous_was_dash = false;
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() {
            sanitized.push(ch.to_ascii_lowercase());
            previous_was_dash = false;
        } else if !previous_was_dash {
            sanitized.push('-');
            previous_was_dash = true;
        }
    }
    let trimmed = sanitized.trim_matches('-').to_string();
    if trimmed.is_empty() {
        "plugin".to_string()
    } else {
        trimmed
    }
}

pub fn sanitize_proto_ident(value: &str) -> String {
    let mut ident = String::new();
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' {
            ident.push(ch);
        } else {
            ident.push('_');
        }
    }

    if ident.is_empty() {
        "field".to_string()
    } else if ident.chars().next().is_some_and(|ch| ch.is_ascii_digit()) {
        format!("_{ident}")
    } else {
        ident
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use op_state_store::{MethodDecl, SideEffect};
