            "operation.plugin.v1.DemoPluginMethods",
            &schema,
        );
        assert!(!bytes.is_empty());

        let decoded = FileDescriptorSet::decode(bytes.as_slice()).expect("decode descriptor set");
        assert_eq!(decoded.file.len(), 1);
        let file = &decoded.file[0];
        assert_eq!(file.package.as_deref(), Some("operation.plugin.v1"));
        assert_eq!(file.service[0].name.as_deref(), Some("DemoPluginMethods"));
        assert_eq!(file.service[0].method.len(), 1);
        assert_eq!(file.service[0].method[0].name.as_deref(), Some("GetState"));
        assert!(file
            .message_type
            .iter()
            .any(|message| message.name.as_deref() == Some("DemoGetStateRequest")));
        assert!(file
            .message_type
            .iter()
            .any(|message| message.name.as_deref() == Some("DemoGetStateResponse")));
        assert!(stable_field_number("alpha") > 0);
        assert_eq!(stable_field_number("alpha"), stable_field_number("alpha"));
    }

    #[test]
    fn blobify_is_deterministic_and_couples_identities() {
        let dbus = || DbusObjectIdentity {
            bus_name: "org.opdbus.v1.plugins".to_string(),
            object_path: "/org/opdbus/v1/plugins/demo".to_string(),
            interface_name: "org.opdbus.v1.Plugin".to_string(),
        };
        let a = blobify_plugin_schema(
            "demo",
            demo_schema(),
            dbus(),
            "operation.plugin.v1",
            "operation.plugin.v1.DemoPluginMethods",
        );
        let b = blobify_plugin_schema(
            "demo",
            demo_schema(),
            dbus(),
            "operation.plugin.v1",
            "operation.plugin.v1.DemoPluginMethods",
        );
        assert_eq!(a.schema_hash, b.schema_hash);
        assert_eq!(a.schema_hash.len(), 64);
        assert_eq!(a.seal(), b.seal());
        assert_eq!(a.methods.len(), 1);
        assert_eq!(a.methods[0].schema_name, "GetState");
        assert_eq!(
