            "operation.plugin.v1.DemoPluginMethods",
        )
    }

    #[test]
    fn seal_roundtrip_zero_copy_and_hash_guard() {
        let blob = demo_blob();
        let bytes = blob.seal();

        let r = BlobRef::new(&bytes).expect("valid blob");
        // Zero-copy: returned slices point inside the sealed image.
        let range = bytes.as_ptr() as usize..bytes.as_ptr() as usize + bytes.len();
        assert!(range.contains(&(r.schema_json().as_ptr() as usize)));
        assert!(range.contains(&(r.descriptor_set().as_ptr() as usize)));
        assert_eq!(r.schema_hash_hex(), blob.schema_hash);

        let round = r.to_blob().unwrap();
        assert_eq!(round.plugin_id, blob.plugin_id);
        assert_eq!(round.schema_json, blob.schema_json);
        assert_eq!(round.grpc.descriptor_set, blob.grpc.descriptor_set);
        assert_eq!(round.methods.len(), blob.methods.len());

        // Corruption is detected.
        let mut bad = bytes.clone();
        let pos = bad.len() - 8;
        bad[pos] ^= 0xff;
        // Either the schema section or a trailing section got flipped; the
        // schema-hash guard or manifest parse must reject it when the schema
        // bytes changed. Flip inside the schema section explicitly:
        let mut bad2 = bytes.clone();
        let schema_off = bad2
            .windows(6)
            .position(|w| w == b"\"demo\"")
            .expect("schema text");
        bad2[schema_off + 1] ^= 0x20;
        assert!(BlobRef::new(&bad2).is_err());
    }
}

//! Persistent per-object blob store — the shm layout that replaces the
//! monolithic `/dev/shm/live-schema.json` runtime shape:
//!
//! ```text
//! /dev/shm/opdbus/plugin-blobs/<plugin_id>.<schema_hash16>.blob
//! ```
//!
//! One D-Bus object, one sealed blob, one schema hash. Writing a new hash for
//! a plugin removes its stale versions. The bridge's in-memory
//! `ActiveReflectionCatalog` stays the reflection authority; this store is
//! the durable (tmpfs) projection other processes can mmap/read zero-copy.

use crate::blob::{PluginObjectBlob, OBJECT_BLOB_SHM_DIR};
use crate::sealed::BlobRef;
use std::io;
use std::path::{Path, PathBuf};

pub struct BlobStore {
    dir: PathBuf,
}

impl BlobStore {
    /// Open (and create) a store directory.
    pub fn open(dir: impl Into<PathBuf>) -> io::Result<Self> {
        let dir = dir.into();
        std::fs::create_dir_all(&dir)?;
        Ok(Self { dir })
    }

    /// Default runtime location on tmpfs (never Btrfs-backed I/O).
    pub fn open_default() -> io::Result<Self> {
        Self::open(OBJECT_BLOB_SHM_DIR)
    }

    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// Persist a sealed blob; drops stale hash versions of the same plugin.
    pub fn write(&self, blob: &PluginObjectBlob) -> io::Result<PathBuf> {
        let path = self.dir.join(blob.sealed_filename());
        std::fs::write(&path, blob.seal())?;
        let prefix = format!("{}.", crate::blob::sanitize_blob_component(&blob.plugin_id));
        for entry in std::fs::read_dir(&self.dir)? {
            let p = entry?.path();
            if p != path {
                if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
                    if name.starts_with(&prefix) && name.ends_with(".blob") {
                        let _ = std::fs::remove_file(&p);
                    }
                }
            }
        }
        Ok(path)
    }

    /// Remove a plugin's blob artifact(s). Returns true if any were removed.
    pub fn remove(&self, plugin_id: &str) -> io::Result<bool> {
        let prefix = format!("{}.", crate::blob::sanitize_blob_component(plugin_id));
        let mut removed = false;
        for entry in std::fs::read_dir(&self.dir)? {
            let p = entry?.path();
            if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
                if name.starts_with(&prefix) && name.ends_with(".blob") {
                    std::fs::remove_file(&p)?;
                    removed = true;
                }
            }
        }
        Ok(removed)
    }

    /// Paths of all sealed blob artifacts (input to btrfs sealing).
    pub fn blob_paths(&self) -> io::Result<Vec<PathBuf>> {
        let mut v = Vec::new();
        for entry in std::fs::read_dir(&self.dir)? {
            let p = entry?.path();
            if p.extension().and_then(|x| x.to_str()) == Some("blob") {
                v.push(p);
            }
        }
        v.sort();
        Ok(v)
    }

    /// Load every valid sealed blob. Corrupt artifacts are skipped (and
    /// reported), never fatal.
    pub fn load_all(&self) -> io::Result<Vec<PluginObjectBlob>> {
        let mut out = Vec::new();
        for path in self.blob_paths()? {
            let bytes = std::fs::read(&path)?;
            match BlobRef::new(&bytes).and_then(|r| r.to_blob()) {
                Ok(blob) => out.push(blob),
                Err(err) => eprintln!("op-blob: skipping {}: {err}", path.display()),
            }
        }
        Ok(out)
    }
}

