            return;
        }
        let dir = tempfile::tempdir().unwrap();
        let store = BlobStore::open(dir.path().join("blobs")).unwrap();
        let schema = PluginSchema::builder("demo")
            .version("1.0.0")
            .method(MethodDecl {
                name: "GetState".to_string(),
                args: simd_json::json!({"type":"object","properties":{}}),
                returns: Some(simd_json::json!({"type":"object","properties":{}})),
                side_effect: SideEffect::Read,
                idempotent: true,
                required_capability: None,
                subid: "obs.service.demo.get-state@v1".to_string(),
            })
            .build();
        let kp = WgKeypair::generate();
        let blob = blobify_plugin_schema_with_identity(
            "demo",
            schema,
            DbusObjectIdentity {
                bus_name: "org.opdbus.v1.plugins".to_string(),
                object_path: "/org/opdbus/v1/plugins/demo".to_string(),
                interface_name: "org.opdbus.v1.Plugin".to_string(),
            },
            "operation.plugin.v1",
            "operation.plugin.v1.DemoPluginMethods",
            Some(kp.public_identity()),
        );
        store.write(&blob).unwrap();

        let image = dir.path().join("opdbus-blobs.btrfs");
        let report =
            seal_blobs_into_btrfs_image(&store.blob_paths().unwrap(), &image).unwrap();
        assert_eq!(report.blob_count, 1);
        assert!(verify_btrfs_image(&image).unwrap());
    }
}

