/// Full-fidelity drift diff between a reference schema and a derived schema
/// (REQ-2.5 drift-guard tests). Empty result ⇒ exact reproduction.
pub fn schema_diffs(reference: &PluginSchema, derived: &PluginSchema) -> Vec<String> {
    let mut d = Vec::new();
    if reference.name != derived.name {
        d.push(format!("name: {:?} -> {:?}", reference.name, derived.name));
    }
    if reference.version != derived.version {
        d.push(format!(
            "version: {:?} -> {:?}",
            reference.version, derived.version
        ));
    }
    if reference.description != derived.description {
        d.push(format!(
            "description: {:?} -> {:?}",
            reference.description, derived.description
        ));
    }
    let (mut ir, mut id) = (
        reference.immutable_paths.clone(),
        derived.immutable_paths.clone(),
    );
    ir.sort();
    id.sort();
    if ir != id {
        d.push(format!("immutable_paths: {ir:?} -> {id:?}"));
    }
    if reference.subids != derived.subids {
        d.push(format!(
            "subids: {:?} -> {:?}",
            reference.subids, derived.subids
        ));
    }
    let keys: std::collections::BTreeSet<&String> = reference
        .fields
        .keys()
        .chain(derived.fields.keys())
        .collect();
    for k in keys {
        match (reference.fields.get(k), derived.fields.get(k)) {
            (Some(r), Some(v)) => field_diffs(&mut d, k, r, v),
            (Some(_), None) => d.push(format!("{k}: DROPPED (in reference, not derived)")),
            (None, Some(_)) => d.push(format!("{k}: ADDED (in derived, not reference)")),
            (None, None) => {}
        }
    }
    d
}

fn field_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldSchema, v: &FieldSchema) {
    if type_tag(&r.field_type) != type_tag(&v.field_type) {
        d.push(format!(
            "{prefix}.type: {} -> {}",
            type_tag(&r.field_type),
            type_tag(&v.field_type)
        ));
    }
    if r.required != v.required {
        d.push(format!(
            "{prefix}.required: {} -> {}",
            r.required, v.required
        ));
    }
    if r.description != v.description {
        d.push(format!(
            "{prefix}.description: {:?} -> {:?}",
            r.description, v.description
        ));
    }
    if r.default != v.default {
        d.push(format!(
            "{prefix}.default: {:?} -> {:?}",
            r.default, v.default
        ));
    }
    if r.example != v.example {
        d.push(format!(
            "{prefix}.example: {:?} -> {:?}",
            r.example, v.example
        ));
    }
    if constraint_tags(&r.constraints) != constraint_tags(&v.constraints) {
        d.push(format!(
            "{prefix}.constraints: {:?} -> {:?}",
            constraint_tags(&r.constraints),
            constraint_tags(&v.constraints)
        ));
    }
    if r.read_only != v.read_only {
        d.push(format!(
            "{prefix}.read_only: {} -> {}",
            r.read_only, v.read_only
        ));
    }
    field_type_diffs(d, prefix, &r.field_type, &v.field_type);
}

fn field_type_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldType, v: &FieldType) {
    match (r, v) {
        (FieldType::Array(r_inner), FieldType::Array(v_inner)) => {
            field_type_diffs(d, &format!("{prefix}[]"), r_inner, v_inner);
        }
        (FieldType::Object(r_map), FieldType::Object(v_map)) => {
            let keys: std::collections::BTreeSet<&String> =
                r_map.keys().chain(v_map.keys()).collect();
            for k in keys {
                match (r_map.get(k), v_map.get(k)) {
                    (Some(rf), Some(vf)) => field_diffs(d, &format!("{prefix}.{k}"), rf, vf),
                    (Some(_), None) => {
                        d.push(format!("{prefix}.{k}: DROPPED (in reference, not derived)"))
                    }
                    (None, Some(_)) => {
                        d.push(format!("{prefix}.{k}: ADDED (in derived, not reference)"))
                    }
                    (None, None) => {}
                }
            }
        }
        (FieldType::OneOf(r_branches), FieldType::OneOf(v_branches)) => {
            if r_branches.len() != v_branches.len() {
                d.push(format!(
                    "{prefix}: one_of branch count differs ({} vs {})",
                    r_branches.len(),
                    v_branches.len()
                ));
            }
            for (i, (rb, vb)) in r_branches.iter().zip(v_branches.iter()).enumerate() {
                field_type_diffs(d, &format!("{prefix}|{i}"), rb, vb);
            }
        }
        _ => {}
    }
}

fn type_tag(t: &FieldType) -> String {
    match t {
        FieldType::String => "string".into(),
        FieldType::Integer => "integer".into(),
        FieldType::Float => "float".into(),
        FieldType::Boolean => "boolean".into(),
        FieldType::Any => "any".into(),
        FieldType::Enum(_) => "enum".into(),
        FieldType::OneOf(branches) => {
            let mut tags: Vec<String> = branches.iter().map(type_tag).collect();
            tags.sort();
            format!("one_of<{}>", tags.join("|"))
        }
        FieldType::Array(i) => format!("array<{}>", type_tag(i)),
        FieldType::Object(m) => {
            let mut entries: Vec<String> = m
                .iter()
                .map(|(k, v)| format!("{k}:{}", type_tag(&v.field_type)))
                .collect();
            entries.sort();
            format!("object{{{}}}", entries.join(","))
        }
    }
}

fn constraint_tags(cs: &[Constraint]) -> Vec<String> {
    let mut v: Vec<String> = cs
        .iter()
        .map(|c| match c {
            Constraint::Min { value } => format!("min:{value}"),
            Constraint::Max { value } => format!("max:{value}"),
            Constraint::Pattern { regex } => format!("pattern:{regex}"),
            Constraint::OneOf { .. } => "oneof".into(),
            Constraint::RequiresField { field } => format!("requires:{field}"),
            Constraint::Custom { validator } => format!("custom:{validator}"),
        })
        .collect();
    v.sort();
    v
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn walks_array_of_objects_with_constraints() {
        // Mirrors what schemars derives for UnixSocketState { sockets: Vec<SocketEndpoint> }.
        let root: JVal = serde_json::from_str(
            r##"{
            "type":"object",
            "properties":{"sockets":{"type":"array","description":"Declared endpoints",
                "items":{"$ref":"#/$defs/SocketEndpoint"}}},
            "required":["sockets"],
            "$defs":{"SocketEndpoint":{"type":"object",
                "properties":{
                    "path":{"type":"string","description":"socket path"},
                    "port":{"type":"integer","minimum":1,"maximum":65535}},
                "required":["path","port"]}}
        }"##,
        )
        .unwrap();
        let s = plugin_schema_from_json("unix_socket", "1.0.0", "desc", &root);

        let sockets = s.fields.get("sockets").expect("sockets field");
        assert!(sockets.required);
        match &sockets.field_type {
            FieldType::Array(inner) => match inner.as_ref() {
                FieldType::Object(props) => {
                    assert!(props.contains_key("path"));
                    let port = props.get("port").unwrap();
                    assert!(port.required);
                    assert_eq!(port.constraints.len(), 2); // Min + Max
                }
                other => panic!("expected object items, got {other:?}"),
            },
            other => panic!("expected array, got {other:?}"),
        }
    }

    #[test]
    fn ingests_root_and_field_subids() {
        let schema = plugin_schema_from_json(
            "subid_test",
            "1.0.0",
            "desc",
            &serde_json::json!({
                "type": "object",
                "x-oscal-subid": "sch.software.test-schema.describe@v1",
                "properties": {
                    "field_a": {
                        "type": "string",
                        "x-oscal-subid": "exp.software.test-field.render@v1"
                    }
                },
                "required": ["field_a"]
            }),
        );
        assert_eq!(
            schema.subids.get("__schema__"),
            Some(&"sch.software.test-schema.describe@v1".to_string())
        );
        assert_eq!(
            schema.subids.get("field_a"),
            Some(&"exp.software.test-field.render@v1".to_string())
        );
    }

    #[test]
    fn reports_nested_mismatch() {
        let mk = |inner_type: &str| {
            plugin_schema_from_json(
                "nested_test",
                "1.0.0",
                "desc",
                &serde_json::json!({
                    "type": "object",
                    "properties": {
                        "wrapper": {
                            "type": "object",
                            "properties": {
                                "inner": { "type": inner_type, "description": "inner field" }
                            },
                            "required": ["inner"]
                        }
                    },
                    "required": ["wrapper"]
                }),
            )
        };
        let diffs = schema_diffs(&mk("string"), &mk("integer"));
        assert!(
            diffs
                .iter()
                .any(|d| d.contains("wrapper.inner") && d.contains("type")),
            "expected nested inner.type diff, got: {diffs:#?}"
        );
    }
}

//! opblob — drive the schema→blob→catalog→btrfs pipeline from the shell.
//!
//! ```text
//! opblob demo-seal <dir>              blobify demo plugins into a catalog dir
//! opblob inspect <file.blob>          print identity, services, methods
//! opblob catalog <dir>                list active services in a catalog dir
//! opblob btrfs-seal <image> <dir>     seal a catalog dir into a btrfs image
//! opblob keygen <keyfile>             generate the account WG identity keypair
//! ```

use op_blob::{
    blob, btrfs, catalog::ActiveReflectionCatalog, demo, descriptor, identity::WgKeypair, BlobRef,
};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let result = match args.as_slice() {
        [cmd, dir] if cmd == "demo-seal" => demo_seal(Path::new(dir)),
        [cmd, file] if cmd == "inspect" => inspect(Path::new(file)),
        [cmd, dir] if cmd == "catalog" => catalog(Path::new(dir)),
        [cmd, image, dir] if cmd == "btrfs-seal" => btrfs_seal(Path::new(image), Path::new(dir)),
        [cmd, keyfile] if cmd == "keygen" => keygen(Path::new(keyfile)),
        _ => {
            eprintln!(
                "usage: opblob demo-seal <dir> | inspect <file.blob> | catalog <dir> | btrfs-seal <image> <dir> | keygen <keyfile>"
            );
            return ExitCode::from(2);
        }
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("opblob: {e}");
            ExitCode::FAILURE
        }
    }
}

fn account_identity(dir: &Path) -> Result<WgKeypair, String> {
    // The account keypair is the identity; the session it defines persists
    // for the life of the account, so reuse the key if present.
    let keyfile = dir.join("identity.key");
    if keyfile.exists() {
        WgKeypair::load(&keyfile).map_err(|e| e.to_string())
    } else {
        let kp = WgKeypair::generate();
        kp.save(&keyfile).map_err(|e| e.to_string())?;
        Ok(kp)
    }
}

fn demo_seal(dir: &Path) -> Result<(), String> {
    std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    let kp = account_identity(dir)?;
    let id = kp.public_identity();
    println!("identity  wg-pub {}  key-id {}", id.wg_public_key, id.key_id);
    println!("session   {} (account-persistent)", id.session.session_id);

    let mut cat = ActiveReflectionCatalog::open(dir).map_err(|e| e.to_string())?;
    for schema in [demo::unix_socket_schema(), demo::wireguard_schema()] {
        let b = blob::blobify_with_identity(&schema, Some(id.clone()));
        let path = cat.upsert_blob(&b).map_err(|e| e.to_string())?;
        println!(
            "sealed    {}  ({} methods, schema {})",
            path.display(),
            b.manifest.methods.len(),
            &b.manifest.schema_hash[..16]
        );
    }
    println!("services:");
    for s in cat.list_services() {
        println!("  {s}");
    }
    Ok(())
}

fn inspect(file: &Path) -> Result<(), String> {
    let bytes = std::fs::read(file).map_err(|e| e.to_string())?;
    let blob = BlobRef::new(&bytes)?;
    let m = blob.manifest()?;
    println!("plugin     {} v{}", m.plugin_id, m.schema_version);
    println!("schema     sha256 {}", m.schema_hash);
    println!("dbus       {} @ {}", m.dbus.interface_name, m.dbus.object_path);
    if let Some(id) = &m.identity {
        println!("identity   wg-pub {}  key-id {}", id.wg_public_key, id.key_id);
        println!(
            "session    {} ({:?})",
            id.session.session_id, id.session.lifespan
        );
    }
    for mm in &m.methods {
        println!(
            "method     {}  {}  cap={}  subid={}",
            mm.schema_name,
            mm.grpc_path,
            mm.required_capability.as_deref().unwrap_or("-"),
            mm.subid
        );
    }
    for f in descriptor::decode_file_summaries(blob.descriptor_set())? {
        println!(
            "descriptor {} pkg={} messages={:?} services={:?}",
            f.name, f.package, f.messages, f.services
        );
    }
    Ok(())
}

fn catalog(dir: &Path) -> Result<(), String> {
    let cat = ActiveReflectionCatalog::open(dir).map_err(|e| e.to_string())?;
    println!("active plugins: {:?}", cat.active_plugins());
    for s in cat.list_services() {
        println!("  {s}");
    }
    Ok(())
}

fn btrfs_seal(image: &Path, dir: &Path) -> Result<(), String> {
    let cat = ActiveReflectionCatalog::open(dir).map_err(|e| e.to_string())?;
    let paths: Vec<PathBuf> = cat.blob_paths();
    let report =
        btrfs::seal_blobs_into_btrfs_image(&paths, image).map_err(|e| e.to_string())?;
    println!(
        "sealed {} blobs into {} ({} bytes, subvolumes={})",
        report.blob_count,
        report.image_path.display(),
        report.image_bytes,
        report.subvolumes
    );
    println!("{}", report.mount_hint);
    Ok(())
}

fn keygen(keyfile: &Path) -> Result<(), String> {
    if keyfile.exists() {
        return Err(format!(
            "{} exists — the keypair is the account identity and its session is account-persistent; refusing to overwrite",
            keyfile.display()
        ));
    }
    let kp = WgKeypair::generate();
    kp.save(keyfile).map_err(|e| e.to_string())?;
    let id = kp.public_identity();
    println!("private key written to {}", keyfile.display());
    println!("public   {}", id.wg_public_key);
    println!("key-id   {}", id.key_id);
    println!("session  {} (account-persistent)", id.session.session_id);
    Ok(())
}

