//! opblob — drive the schema->blob->store->btrfs pipeline from the shell.
//!
//! ```text
//! opblob inspect <file.blob>          print identity, services, methods
//! opblob catalog <dir>                list active plugins from a BlobStore dir
//! opblob btrfs-seal <image> <dir>     seal a store dir into a btrfs image
//! opblob keygen <keyfile>             generate the account WG identity keypair
//! opblob demo-seal <dir>              blobify the zeroclaw schema (demo feature)
//! ```

use op_blob::{
    blobify_plugin_schema_with_identity, btrfs, descriptor, identity::WgKeypair, sealed::BlobRef,
    store::BlobStore,
};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let result = match args.as_slice() {
        [cmd, file] if cmd == "inspect" => inspect(Path::new(file)),
        [cmd, dir] if cmd == "catalog" => catalog(Path::new(dir)),
        [cmd, image, dir] if cmd == "btrfs-seal" => btrfs_seal(Path::new(image), Path::new(dir)),
        [cmd, keyfile] if cmd == "keygen" => keygen(Path::new(keyfile)),
        #[cfg(feature = "demo")]
        [cmd, dir] if cmd == "demo-seal" => demo_seal(Path::new(dir)),
        _ => {
            eprintln!(
                "usage: opblob inspect <file.blob> | catalog <dir> | btrfs-seal <image> <dir> | keygen <keyfile>"
            );
            #[cfg(feature = "demo")]
            eprintln!("       opblob demo-seal <dir>");
            #[cfg(not(feature = "demo"))]
            eprintln!("       (demo-seal requires --features demo)");
            return ExitCode::from(2);
        }
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("opblob: {e}");
            ExitCode::FAILURE
        }
    }
}

fn inspect(file: &Path) -> Result<(), String> {
    let bytes = std::fs::read(file).map_err(|e| e.to_string())?;
    let blob = BlobRef::new(&bytes)?;
    let manifest_json = blob.manifest_json();
    let manifest: op_blob::blob::PluginObjectBlob =
        serde_json::from_str(manifest_json).map_err(|e| format!("manifest parse: {e}"))?;

    println!("plugin     {} v{}", manifest.plugin_id, manifest.schema_version);
    println!("schema     sha256 {}", manifest.schema_hash);
    println!(
        "dbus       {} @ {}",
        manifest.dbus.interface_name, manifest.dbus.object_path
    );
    if let Some(id) = &manifest.identity {
        println!("identity   wg-pub {}  key-id {}", id.wg_public_key, id.key_id);
        println!(
            "session    {} (account-persistent)",
            id.session.session_id
        );
    }
    if let Some(legacy) = &manifest.grpc.legacy_service_name {
        println!("grpc-legacy {}", legacy);
    }
    for mm in &manifest.methods {
        println!(
            "method     {}  {}  cap={}  subid={}",
            mm.schema_name,
            mm.grpc_path,
            mm.required_capability.as_deref().unwrap_or("-"),
            mm.subid
        );
    }
    for f in descriptor::decode_file_summaries(blob.descriptor_set())? {
        println!(
            "descriptor {} pkg={} messages={:?} services={:?}",
            f.name, f.package, f.messages, f.services
        );
    }
    Ok(())
}

fn catalog(dir: &Path) -> Result<(), String> {
    let store = BlobStore::open(dir).map_err(|e| e.to_string())?;
    let blobs = store.load_all().map_err(|e| e.to_string())?;
    println!("active plugins: {}", blobs.len());
    for blob in &blobs {
        println!(
            "  {} v{} ({} methods, hash {})",
            blob.plugin_id,
            blob.schema_version,
            blob.methods.len(),
            &blob.schema_hash[..16]
        );
        if let Some(legacy) = &blob.grpc.legacy_service_name {
            println!("    legacy-service: {}", legacy);
        }
        for svc in &blob.grpc.services {
            println!("    service: {}", svc);
        }
    }
    Ok(())
}

fn btrfs_seal(image: &Path, dir: &Path) -> Result<(), String> {
    let store = BlobStore::open(dir).map_err(|e| e.to_string())?;
    let paths: Vec<PathBuf> = store.blob_paths().map_err(|e| e.to_string())?;
    if paths.is_empty() {
        return Err("no blobs in store directory".into());
    }
    let report = btrfs::seal_blobs_into_btrfs_image(&paths, image).map_err(|e| e.to_string())?;
    println!(
        "sealed {} blobs into {} ({} bytes, subvolumes={})",
        report.blob_count,
        report.image_path.display(),
        report.image_bytes,
        report.subvolumes
    );
    println!("{}", report.mount_hint);
    Ok(())
}

fn keygen(keyfile: &Path) -> Result<(), String> {
    if keyfile.exists() {
        return Err(format!(
            "{} exists — the keypair is the account identity and its session is \
             account-persistent; refusing to overwrite",
            keyfile.display()
        ));
    }
    let kp = WgKeypair::generate();
    kp.save(keyfile).map_err(|e| e.to_string())?;
    let id = kp.public_identity();
    println!("private key written to {}", keyfile.display());
    println!("public   {}", id.wg_public_key);
    println!("key-id   {}", id.key_id);
    println!("session  {} (account-persistent)", id.session.session_id);
    Ok(())
}

#[cfg(feature = "demo")]
fn demo_seal(dir: &Path) -> Result<(), String> {
    std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    let keyfile = dir.join("identity.key");
    let kp = if keyfile.exists() {
        WgKeypair::load(&keyfile).map_err(|e| e.to_string())?
    } else {
        let kp = WgKeypair::generate();
        kp.save(&keyfile).map_err(|e| e.to_string())?;
        kp
    };
    let id = kp.public_identity();
    println!("identity  wg-pub {}  key-id {}", id.wg_public_key, id.key_id);
    println!("session   {} (account-persistent)", id.session.session_id);

    let store = BlobStore::open(dir).map_err(|e| e.to_string())?;
    let schema = op_plugins::state_plugins::zeroclaw::zeroclaw_plugin_schema();
    let blob = blobify_plugin_schema_with_identity("zeroclaw", schema, Some(id.clone()));
    let path = store.write(&blob).map_err(|e| e.to_string())?;
    println!(
        "sealed    {}  ({} methods, schema {})",
        path.display(),
        blob.methods.len(),
        &blob.schema_hash[..16]
    );
    println!("services:");
    for svc in &blob.grpc.services {
        println!("  {svc}");
    }
    if let Some(legacy) = &blob.grpc.legacy_service_name {
        println!("  (legacy) {legacy}");
    }
    Ok(())
}

